package com.bocsoft.sqleditor.history;
import com.bocsoft.sqleditor.config.SqlEditorProperties;import com.bocsoft.sqleditor.history.persistence.ExecutionHistoryMapper;import java.time.Clock;import javax.annotation.PostConstruct;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class HistoryMaintenance {private final ExecutionHistoryMapper mapper;private final SqlEditorProperties.History config;private final Clock clock;public HistoryMaintenance(ExecutionHistoryMapper mapper,SqlEditorProperties p,Clock clock){this.mapper=mapper;this.config=p.getHistory();this.clock=clock;}@PostConstruct public void recover(){java.time.Instant now=clock.instant();mapper.markStale(now.minusSeconds(config.getStaleRunningMinutes()*60L),now);}@Scheduled(cron="0 15 2 * * *")public void cleanup(){if(config.getRetentionDays()>0)mapper.deleteFinishedBefore(clock.instant().minusSeconds(config.getRetentionDays()*86400L));}}
